import java.util.*;
import java.lang.*;
import java.io.*;

    
    
class Codechef
{
        static long[] a,p;
        static int n;
        static long value(int x, int y, int z)
        {
            return Math.max(6L *x, Math.max(4L*(x+y),3L*(x+y+z)));
        }
	public static void main (String[] args) throws java.lang.Exception
	{
		// your code goes here
		Scanner sc = new Scanner(System.in);
		int t = sc.nextInt();
		while(t-->0)
		{
		    n = sc.nextInt();
		    int m =3*n;
		    a= new long[m];
		    for(int i=0;i<m;i++)
		    a[i]=sc.nextInt();
		    Arrays.sort(a);
		    long[] b = new long[m];
		    for(int i=0;i<m;i++)
		    b[i]= a[m-1-i];
		    p=new long[m+1];
		    for(int i=0;i<m;i++)
		    {
		        p[i+1] = p[i]+b[i];
		    }
		    long ans =0;
		    for(int x=0;x<=n;x++)
		    {
		        int l=0,r=n-x;
		        while(l<r)
		        {
		            int mid = (l+r+1)/2;
		            if(mid==0 || b[x+2*mid-2]+b[x+2*mid-1]>=3L*b[3*n-2*x-mid])
		            l=mid;
		            else r=mid-1;
		        }
		        int y=l;
		        long cur = 2*p[x]+p[x+2*y]+3*p[3*n-2*x-y];
		        ans=Math.max(ans,cur);
		    }
		    System.out.println(ans);
		}
		
	}
}
